if (!/^[a-z0-9_-]+\.html$/.test(fixture)) {
  process.stderr.write("fixture must be a testdata HTML basename\n");
  process.exit(2);
}
const html = await readFile(join(here, "..", "testdata", fixture), "utf8");
const browser = await chromium.launch({ headless: true, executablePath: chrome });
try {
  const page = await browser.newPage();
  await page.setContent(html);
  if (fixture === "order_dashboard.html") {
    await page.waitForFunction(() => document.querySelectorAll("tbody tr").length === 200);
  }
  process.stdout.write(await page.locator("body").ariaSnapshot());
} finally {
  await browser.close();
}

package browse

import (
	"context"
	"encoding/json"
	"errors"
	"log/slog"
	"math"
	"net/url"
	"strings"
	"sync"
	"time"

	"github.com/JuliusBrussee/caveman/engine"
	"github.com/JuliusBrussee/caveman/engine/tokens"
	"github.com/JuliusBrussee/caveman/mcp"
)

const (
	ToolSnapshot = "browser_snapshot"
	ToolAct      = "browser_act"
	ToolEval     = "browser_eval"
	ToolRecover  = "browser_recover"

	maxSnapshotWaitMS  = 30_000
	maxQueryBytes      = 4 << 10
	maxDataURLBytes    = 1 << 20
	maxActionTextBytes = 1 << 20
)

type Driver interface {
	Snapshot(ctx context.Context, url string, wait time.Duration) ([]byte, error)
	Act(ctx context.Context, req ActionRequest, target Target) (ActionResult, error)
	Eval(ctx context.Context, expression string) (any, error)
	Close() error
}

type Session struct {
	eng    *engine.Engine
	driver Driver
	log    *slog.Logger

	mu      sync.Mutex
	targets map[string]Target
}

type Target struct {
	BackendDOMNodeID int    `json:"backendDOMNodeId"`
	FrameID          string `json:"frameId,omitempty"`
	NodeID           string `json:"nodeId,omitempty"`
}

type ActionRequest struct {
	Action string `json:"action"`
	UID    string `json:"uid"`
	Text   string `json:"text"`
	Option string `json:"option"`
}

type ActionResult struct {
	OK      bool   `json:"ok"`
	UID     string `json:"uid,omitempty"`
	Settled bool   `json:"settled"`
	Note    string `json:"note,omitempty"`
}

func NewSession(eng *engine.Engine, driver Driver, log *slog.Logger) *Session {
	if log == nil {
		log = slog.New(slog.NewTextHandler(discard{}, nil))
	}
	return &Session{eng: eng, driver: driver, log: log, targets: map[string]Target{}}
}

func (s *Session) Close() error {
	if s.driver == nil {
		return nil
	}
	return s.driver.Close()
}

func BrowserTools(s *Session) []mcp.Tool {
	return []mcp.Tool{
		{
			Name:        ToolSnapshot,
			Description: "Compact recovery-backed AX tree. URL navigates; query keeps task matches. Counts inferred.",
			InputSchema: mcp.ObjectSchema(map[string]any{
				"url":   mcp.StringProp("http(s), about:blank, or data:text/html"),
				"wait":  map[string]any{"type": "number", "description": "Wait ms, 0..30000."},
				"query": mcp.StringProp("Terms for focused nodes."),
			}),
			Handler: s.snapshotTool,
		},
		{
			Name:        ToolAct,
			Description: "Act on latest UID. Resnapshot verifies state.",
			InputSchema: mcp.ObjectSchema(map[string]any{
				"action": mcp.StringProp("click|type|select|scroll|wait"),
				"uid":    mcp.StringProp("Latest snapshot UID."),
				"text":   mcp.StringProp("Type/select text."),
				"option": mcp.StringProp("Select value/label."),
			}, "action"),
			Handler: s.actTool,
		},
		{
			Name:        ToolEval,
			Description: "Run JavaScript in current page.",
			InputSchema: mcp.ObjectSchema(map[string]any{
				"expression": mcp.StringProp("JavaScript expression."),
			}, "expression"),
			Handler: s.evalTool,
		},
		{
			Name:        ToolRecover,
			Description: "Recover exact raw AX bytes; query optionally narrows.",
			InputSchema: mcp.ObjectSchema(map[string]any{
				"recovery_handle": mcp.StringProp("Snapshot recovery handle."),
				"query":           mcp.StringProp("Recovery terms."),
			}, "recovery_handle"),
			Handler:         s.recoverTool,
			ExemptResultCap: true,
		},
	}
}

type snapshotPayload struct {
	UIDs             string  `json:"uids"`
	FullSnapshotPath *string `json:"full_snapshot_path,omitempty"`
	RecoveryHandle   *string `json:"recovery_handle"`
	TokensBefore     int     `json:"tokens_before"`
	ViewTokens       int     `json:"view_tokens"`
	TokensAfter      int     `json:"tokens_after"`
	Ratio            float64 `json:"ratio"`
	Basis            string  `json:"basis"`
}

func (s *Session) snapshotTool(args json.RawMessage) mcp.ToolResult {
	var a struct {
		URL    string  `json:"url"`
		WaitMS float64 `json:"wait"`
		Query  string  `json:"query"`
	}
	if err := json.Unmarshal(args, &a); err != nil {
		return mcp.ToolError("cave_invalid_arguments", "snapshot: invalid arguments")
	}
	if code, message := validateSnapshotArgs(a.URL, a.WaitMS, a.Query); code != "" {
		return mcp.ToolError(code, message)
	}
	if s.driver == nil || s.eng == nil {
		return mcp.ToolError("cave_browser_unavailable", "browser session unavailable")
	}
	wait := time.Duration(a.WaitMS * float64(time.Millisecond))
	ctx, cancel := context.WithTimeout(context.Background(), snapshotTimeout(wait))
	defer cancel()

	raw, err := s.driver.Snapshot(ctx, a.URL, wait)
	if err != nil {
		s.log.Warn("browser snapshot failed", "err", err)
		return mcp.ToolError("cave_browser_snapshot_failed", "snapshot failed")
	}
	res, err := s.eng.Compress(raw, engine.Options{Mode: engine.ModeCompress, Type: engine.TypeA11y, Query: a.Query})
	if err != nil {
		s.log.Warn("a11y compress failed", "err", err)
		return mcp.ToolError("cave_browser_snapshot_failed", "snapshot recovery unavailable")
	}
	if res.RecoveryHandle == "" {
		// Pass-through: the engine did not produce a recovery-backed uid view
		// (a tree that did not get smaller, or no CCR store). The uid map is this
		// tool's contract, not a side effect of a compression ratio, so we must
		// NOT (a) dump the raw AX tree into `uids` — hundreds of KB of raw JSON is
		// strictly worse than not using Browse — nor (b) wipe the prior page's uid
		// cache. Fail closed and keep prior targets so acting stays predictable
		// (issue #140).
		s.log.Warn("a11y snapshot did not compress; refusing raw-tree pass-through",
			"ratio", res.Ratio, "tokens_before", res.TokensBefore)
		return mcp.ToolError("cave_browser_snapshot_uncompressed",
			"snapshot did not compress to a uid view; raw tree withheld and prior uids retained")
	}
	h := res.RecoveryHandle
	targets, err := s.targetsForHandle(h)
	if err != nil {
		s.log.Warn("a11y uid metadata unavailable", "err", err)
		return mcp.ToolError("cave_browser_snapshot_failed", "snapshot uid map unavailable; prior uids retained")
	}
	payload, text := finalizeSnapshotPayload(snapshotPayload{
		UIDs:           string(res.Output),
		RecoveryHandle: &h,
		TokensBefore:   res.TokensBefore,
		ViewTokens:     res.TokensAfter,
		Basis:          res.Basis,
	})
	if payload.TokensAfter >= payload.TokensBefore {
		return mcp.ToolError("cave_browser_snapshot_uncompressed",
			"agent-visible snapshot was not smaller than raw AX; prior uids retained")
	}
	s.replaceTargets(targets)
	return mcp.ToolRawText(text)
}

func snapshotTimeout(wait time.Duration) time.Duration {
	base := 15 * time.Second
	if wait > 0 {
		base += wait
	}
	return base
}

func (s *Session) targetsForHandle(handle string) (map[string]Target, error) {
	meta, err := s.eng.RetrieveMetadata(handle)
	if err != nil {
		return nil, err
	}
	if len(meta) == 0 {
		return nil, errors.New("empty a11y recovery metadata")
	}
	var decoded struct {
		UIDs map[string]Target `json:"uids"`
	}
	if err := json.Unmarshal(meta, &decoded); err != nil {
		return nil, err
	}
	if decoded.UIDs == nil {
		decoded.UIDs = map[string]Target{}
	}
	return decoded.UIDs, nil
}

func finalizeSnapshotPayload(payload snapshotPayload) (snapshotPayload, string) {
	counter := tokens.Default()
	for range 8 {
		encoded, _ := json.Marshal(payload)
		delivered := counter.Count(encoded)
		ratio := 0.0
		if payload.TokensBefore > 0 && delivered < payload.TokensBefore {
			ratio = float64(payload.TokensBefore-delivered) / float64(payload.TokensBefore)
		}
		if payload.TokensAfter == delivered && payload.Ratio == ratio {
			return payload, string(encoded)
		}
		payload.TokensAfter = delivered
		payload.Ratio = ratio
	}
	encoded, _ := json.Marshal(payload)
	return payload, string(encoded)
}

func validateSnapshotArgs(rawURL string, waitMS float64, query string) (string, string) {
	if math.IsNaN(waitMS) || math.IsInf(waitMS, 0) || waitMS < 0 || waitMS > maxSnapshotWaitMS {
		return "cave_invalid_arguments", "snapshot: wait must be between 0 and 30000 milliseconds"
	}
	if len(query) > maxQueryBytes {
		return "cave_invalid_arguments", "snapshot: query too large"
	}
	if rawURL == "" {
		return "", ""
	}
	if len(rawURL) > maxDataURLBytes {
		return "cave_invalid_arguments", "snapshot: url too large"
	}
	parsed, err := url.Parse(rawURL)
	if err != nil || parsed.Scheme == "" {
		return "cave_invalid_arguments", "snapshot: absolute URL required"
	}
	switch strings.ToLower(parsed.Scheme) {
	case "http", "https":
		if parsed.Host == "" {
			return "cave_invalid_arguments", "snapshot: URL host required"
		}
		return "", ""
	case "about":
		if strings.EqualFold(rawURL, "about:blank") {
			return "", ""
		}
	case "data":
		if strings.HasPrefix(strings.ToLower(rawURL), "data:text/html,") ||
			strings.HasPrefix(strings.ToLower(rawURL), "data:text/html;") {
			return "", ""
		}
	}
	return "cave_browser_url_denied", "snapshot: URL scheme denied; use http(s), about:blank, or data:text/html"
}

func (s *Session) replaceTargets(targets map[string]Target) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.targets = map[string]Target{}
	for uid, target := range targets {
		s.targets[uid] = target
	}
}

func (s *Session) LoadTargets(targets map[string]Target) {
	s.replaceTargets(targets)
}

func (s *Session) TargetsSnapshot() map[string]Target {
	s.mu.Lock()
	defer s.mu.Unlock()
	out := make(map[string]Target, len(s.targets))
	for uid, target := range s.targets {
		out[uid] = target
	}
	return out
}

func (s *Session) actTool(args json.RawMessage) mcp.ToolResult {
	var req ActionRequest
	if err := json.Unmarshal(args, &req); err != nil || req.Action == "" {
		return mcp.ToolError("cave_invalid_arguments", "act: missing action")
	}
	if len(req.Text) > maxActionTextBytes || len(req.Option) > maxActionTextBytes {
		return mcp.ToolError("cave_invalid_arguments", "act: text too large")
	}
	if s.driver == nil {
		return mcp.ToolError("cave_browser_unavailable", "browser session unavailable")
	}
	if req.Action == "wait" {
		time.Sleep(250 * time.Millisecond)
		return mcp.ToolText(ActionResult{OK: true, UID: req.UID, Settled: true})
	}
	if req.Action != "click" && req.Action != "type" && req.Action != "select" && req.Action != "scroll" {
		return mcp.ToolError("cave_unknown_action", "unsupported browser action")
	}
	if req.UID == "" {
		return mcp.ToolError("cave_invalid_arguments", "act: uid required")
	}
	if req.Action == "type" && req.Text == "" {
		return mcp.ToolError("cave_invalid_arguments", "act: text required for type")
	}
	target, ok := s.lookupTarget(req.UID)
	if !ok {
		return mcp.ToolError("cave_unknown_uid", "no element found for uid")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	res, err := s.driver.Act(ctx, req, target)
	if err != nil {
		s.log.Warn("browser action failed", "action", req.Action, "uid", req.UID, "err", err)
		return mcp.ToolError("cave_browser_action_failed", "action failed")
	}
	if !res.OK {
		return mcp.ToolError("cave_browser_action_failed", "action was not completed")
	}
	res.UID = req.UID
	return mcp.ToolText(res)
}

func (s *Session) lookupTarget(uid string) (Target, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	target, ok := s.targets[uid]
	return target, ok
}

func (s *Session) evalTool(args json.RawMessage) mcp.ToolResult {
	var a struct {
		Expression string `json:"expression"`
	}
	if err := json.Unmarshal(args, &a); err != nil || strings.TrimSpace(a.Expression) == "" || len(a.Expression) > maxActionTextBytes {
		return mcp.ToolError("cave_invalid_arguments", "eval: missing expression")
	}
	if s.driver == nil {
		return mcp.ToolError("cave_browser_unavailable", "browser session unavailable")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	result, err := s.driver.Eval(ctx, a.Expression)
	if err != nil {
		s.log.Warn("browser eval failed", "err", err)
		return mcp.ToolError("cave_browser_eval_failed", "eval failed")
	}
	return mcp.ToolText(map[string]any{"result": result})
}

func (s *Session) recoverTool(args json.RawMessage) mcp.ToolResult {
	var a struct {
		RecoveryHandle string `json:"recovery_handle"`
		Query          string `json:"query"`
	}
	if err := json.Unmarshal(args, &a); err != nil || a.RecoveryHandle == "" || len(a.RecoveryHandle) > 512 || len(a.Query) > maxQueryBytes {
		return mcp.ToolError("cave_invalid_arguments", "recover: missing recovery_handle")
	}
	if s.eng == nil {
		return mcp.ToolError("cave_browser_unavailable", "browser recovery unavailable")
	}
	original, err := s.eng.RetrieveQuery(a.RecoveryHandle, a.Query)
	if err != nil {
		return mcp.ToolError("cave_unknown_handle", "no original found for handle")
	}
	return mcp.ToolRawText(string(original))
}

type discard struct{}

func (discard) Write(p []byte) (int, error) { return len(p), nil }

package browse

import (
	"context"
	"encoding/json"
	"errors"
	"math"
	"os"
	"strings"
	"testing"
	"time"

	"github.com/JuliusBrussee/caveman/engine"
	"github.com/JuliusBrussee/caveman/engine/ccr"
	"github.com/JuliusBrussee/caveman/engine/tokens"
	"github.com/JuliusBrussee/caveman/mcp"
)

type fakeDriver struct {
	raw         []byte
	snapshot    int
	lastURL     string
	lastAct     ActionRequest
	lastTgt     Target
	evalValue   any
	snapshotErr error
	closeErr    error
	closed      bool
}

func (f *fakeDriver) Snapshot(_ context.Context, url string, _ time.Duration) ([]byte, error) {
	f.snapshot++
	f.lastURL = url
	if f.snapshotErr != nil {
		return nil, f.snapshotErr
	}
	return f.raw, nil
}

func (f *fakeDriver) Act(_ context.Context, req ActionRequest, target Target) (ActionResult, error) {
	f.lastAct = req
	f.lastTgt = target
	if req.Text == "explode" {
		return ActionResult{}, errors.New("boom")
	}
	return ActionResult{OK: true, Settled: true}, nil
}

func (f *fakeDriver) Eval(_ context.Context, expression string) (any, error) {
	if expression == "throw" {
		return nil, errors.New("boom")
	}
	return f.evalValue, nil
}

func (f *fakeDriver) Close() error {
	f.closed = true
	return f.closeErr
}

func testSession(t *testing.T) (*Session, *fakeDriver) {
	t.Helper()
	raw, err := os.ReadFile("../engine/compressors/testdata/axtree_cdp_local_page.json")
	if err != nil {
		t.Fatal(err)
	}
	store, err := ccr.OpenMemory()
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { store.Close() })
	driver := &fakeDriver{raw: raw, evalValue: map[string]any{"ok": true}}
	return NewSession(engine.New(store, nil), driver, nil), driver
}

func TestBrowserToolsExactlyFour(t *testing.T) {
	s, _ := testSession(t)
	tools := BrowserTools(s)
	got := make([]string, len(tools))
	for i, tool := range tools {
		got[i] = tool.Name
		if tool.Description == "" || len(tool.InputSchema) == 0 {
			t.Fatalf("tool %s missing description/schema", tool.Name)
		}
	}
	want := []string{ToolSnapshot, ToolAct, ToolEval, ToolRecover}
	if strings.Join(got, ",") != strings.Join(want, ",") {
		t.Fatalf("tools=%v want=%v", got, want)
	}
	if !tools[3].ExemptResultCap {
		t.Fatal("byte-exact browser_recover must be exempt from generic MCP result cap")
	}
	definitions := make([]map[string]any, 0, len(tools))
	for _, tool := range tools {
		definitions = append(definitions, map[string]any{
			"name": tool.Name, "description": tool.Description, "inputSchema": tool.InputSchema,
		})
	}
	catalog, err := json.Marshal(definitions)
	if err != nil {
		t.Fatal(err)
	}
	catalogTokens := tokens.Default().Count(catalog)
	if catalogTokens > 300 {
		t.Fatalf("four-tool catalog exceeds 300-token budget: %d", catalogTokens)
	}
	t.Logf("browser MCP catalog tokens=%d", catalogTokens)
}

func TestSessionCloseAndTargetSnapshotsAreSafe(t *testing.T) {
	if err := NewSession(nil, nil, nil).Close(); err != nil {
		t.Fatalf("nil driver close: %v", err)
	}

	s, driver := testSession(t)
	s.LoadTargets(map[string]Target{"u1": {BackendDOMNodeID: 7}})
	got := s.TargetsSnapshot()
	got["u1"] = Target{BackendDOMNodeID: 99}
	got["injected"] = Target{BackendDOMNodeID: 8}
	if original, ok := s.lookupTarget("u1"); !ok || original.BackendDOMNodeID != 7 {
		t.Fatalf("snapshot mutated session target: %+v ok=%v", original, ok)
	}
	if _, ok := s.lookupTarget("injected"); ok {
		t.Fatal("snapshot map leaked writes into session")
	}

	driver.closeErr = errors.New("close failed")
	if err := s.Close(); !errors.Is(err, driver.closeErr) {
		t.Fatalf("Close error = %v", err)
	}
	if !driver.closed {
		t.Fatal("Close did not reach driver")
	}
}

func TestUnavailableSessionFailsClosedWithoutPanicking(t *testing.T) {
	s := NewSession(nil, nil, nil)
	for name, got := range map[string]mcp.ToolResult{
		"snapshot": s.snapshotTool(jsonArgs(t, map[string]any{})),
		"act":      s.actTool(jsonArgs(t, map[string]any{"action": "wait"})),
		"eval":     s.evalTool(jsonArgs(t, map[string]any{"expression": "1+1"})),
		"recover":  s.recoverTool(jsonArgs(t, map[string]any{"recovery_handle": "ccr_missing"})),
	} {
		if !got.IsError || !strings.Contains(got.Content[0].Text, "cave_browser_unavailable") {
			t.Fatalf("%s unavailable result = %+v", name, got)
		}
	}
}

func TestSnapshotCachesUIDTargetsAndRecoversExactAXTree(t *testing.T) {
	s, driver := testSession(t)
	tr := s.snapshotTool(jsonArgs(t, map[string]any{"url": "http://127.0.0.1:3000"}))
	if tr.IsError {
		t.Fatalf("snapshot failed: %s", tr.Content[0].Text)
	}
	var p snapshotPayload
	decodeToolText(t, tr, &p)
	if p.Basis != engine.BasisInferred || p.Ratio <= 0 || p.RecoveryHandle == nil {
		t.Fatalf("snapshot did not report inferred recovery-backed reduction: %+v", p)
	}
	if driver.lastURL != "http://127.0.0.1:3000" {
		t.Fatalf("url not forwarded: %q", driver.lastURL)
	}
	if !strings.Contains(p.UIDs, `[ua] button "Save settings"`) {
		t.Fatalf("snapshot missing expected uid/button:\n%s", p.UIDs)
	}
	if p.ViewTokens <= 0 || p.ViewTokens >= p.TokensAfter {
		t.Fatalf("view/delivery accounting invalid: %+v", p)
	}
	delivered := tokens.Default().Count([]byte(tr.Content[0].Text))
	if p.TokensAfter != delivered {
		t.Fatalf("tokens_after=%d must count exact agent-visible payload=%d", p.TokensAfter, delivered)
	}
	wantRatio := float64(p.TokensBefore-p.TokensAfter) / float64(p.TokensBefore)
	if math.Abs(p.Ratio-wantRatio) > 1e-12 {
		t.Fatalf("delivery ratio=%v want=%v", p.Ratio, wantRatio)
	}
	if p.TokensAfter > 128 {
		t.Fatalf("captured fixture exceeded agent-visible token budget: %+v", p)
	}
	t.Logf("captured snapshot tokens raw=%d view=%d delivered=%d", p.TokensBefore, p.ViewTokens, p.TokensAfter)
	target, ok := s.lookupTarget("ua")
	if !ok || target.BackendDOMNodeID != 10 {
		t.Fatalf("uid target cache missing button: %+v ok=%v", target, ok)
	}

	recovered := s.recoverTool(jsonArgs(t, map[string]any{"recovery_handle": *p.RecoveryHandle}))
	if recovered.IsError || recovered.Content[0].Text != string(driver.raw) {
		t.Fatalf("recover not byte-exact: error=%v", recovered.IsError)
	}
	if strings.Contains(recovered.Content[0].Text, "verified") || strings.Contains(p.UIDs, "verified") {
		t.Fatal("browse path must never emit verified")
	}
}

// iframeAXTree mimics Accessibility.getFullAXTree for a host frame that embeds
// an <iframe>: node "3" is the iframe boundary whose child document root "100"
// lives in another frame and is therefore absent from this payload.
const iframeAXTree = `[
  {"nodeId":"1","role":{"value":"RootWebArea"},"name":{"value":"Host Page"},"backendDOMNodeId":1,"childIds":["2","3"]},
  {"nodeId":"2","role":{"value":"button"},"name":{"value":"Save settings"},"backendDOMNodeId":10},
  {"nodeId":"3","role":{"value":"Iframe"},"name":{"value":"Embedded report"},"backendDOMNodeId":11,"childIds":["100"]}
]`

// TestSnapshotIframeTreeStillCompressesToUIDs is the issue #140 pass-through
// regression at the tool boundary: before the fix an iframe's dangling childId
// made the AX tree reject, the engine passed the raw JSON through, and
// snapshotTool dumped that raw tree into `uids` with a nil recovery handle.
// After the fix the frame-visible nodes compress into a usable uid map.
func TestSnapshotIframeTreeStillCompressesToUIDs(t *testing.T) {
	store, err := ccr.OpenMemory()
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { store.Close() })
	s := NewSession(engine.New(store, nil), &fakeDriver{raw: []byte(iframeAXTree)}, nil)

	tr := s.snapshotTool(jsonArgs(t, map[string]any{"url": "http://host"}))
	if tr.IsError {
		t.Fatalf("iframe snapshot must not fail closed: %s", tr.Content[0].Text)
	}
	var p snapshotPayload
	decodeToolText(t, tr, &p)
	if p.RecoveryHandle == nil || p.Ratio <= 0 || p.Basis != engine.BasisInferred {
		t.Fatalf("iframe snapshot did not produce a recovery-backed reduction: %+v", p)
	}
	if !strings.Contains(p.UIDs, `[ua] button "Save settings"`) {
		t.Fatalf("frame-visible button lost its uid handle:\n%s", p.UIDs)
	}
	if strings.Contains(p.UIDs, `childIds`) || strings.Contains(p.UIDs, `nodeId`) {
		t.Fatalf("raw AX tree was dumped into uids instead of the curated view:\n%s", p.UIDs)
	}
	if target, ok := s.lookupTarget("ua"); !ok || target.BackendDOMNodeID != 10 {
		t.Fatalf("uid target cache missing iframe-page button: %+v ok=%v", target, ok)
	}
}

// TestSnapshotPassThroughFailsClosedAndKeepsUIDCache pins the second half of
// issue #140: when the engine genuinely cannot produce a recovery-backed view
// (here: no CCR store, so the S4 a11y compressor fails closed to pass-through),
// snapshotTool must return a fail-closed error rather than dumping the raw tree
// into `uids`, and must NOT wipe the previously cached uid targets.
func TestSnapshotPassThroughFailsClosedAndKeepsUIDCache(t *testing.T) {
	// engine.New(nil, nil): no store → S4 a11y compressor passes through.
	s := NewSession(engine.New(nil, nil), &fakeDriver{raw: []byte(iframeAXTree)}, nil)
	s.LoadTargets(map[string]Target{"u1": {BackendDOMNodeID: 7}})

	tr := s.snapshotTool(jsonArgs(t, map[string]any{"url": "http://host"}))
	if !tr.IsError || !strings.Contains(tr.Content[0].Text, "cave_browser_snapshot_uncompressed") {
		t.Fatalf("pass-through snapshot must fail closed, got %+v", tr)
	}
	if strings.Contains(tr.Content[0].Text, `"nodeId"`) || strings.Contains(tr.Content[0].Text, `"childIds"`) {
		t.Fatalf("raw AX tree leaked into pass-through error payload: %s", tr.Content[0].Text)
	}
	if target, ok := s.lookupTarget("u1"); !ok || target.BackendDOMNodeID != 7 {
		t.Fatalf("pass-through wiped the prior uid cache: %+v ok=%v", target, ok)
	}
}

