	}
	if driver.snapshot != 0 {
		t.Fatalf("invalid snapshot reached browser %d times", driver.snapshot)
	}
	if _, ok := s.lookupTarget("prior"); !ok {
		t.Fatal("rejected snapshot wiped prior uid cache")
	}
}

